+                const identity = String(parts[3] || '').toLowerCase().replace(/\s+/g, ' ');
+                const primaryError = String(parts[4] || '').toLowerCase().replace(/\s+/g, ' ');
+                if (identity.length < 5 || primaryError.length < 3) {
