+              }
+
+              for (const entry of existingEntries) {
+                results.issues.push({
+                  pipeline: entry.pipeline,
+                  fingerprint: entry.fingerprint,
+                  disposition: 'existing',
+                  issue_number: Number(entry.issue_number),
+                  coverage_proof: entry.coverage_proof,
+                });
