+                  throw new Error(`GitHub did not preserve the validated title/body for issue #${response.data.number}.`);
+                }
+
+                result.metadata_preserved = true;
+                persistResults();
+                core.info(`Created issue #${response.data.number}: ${issue.Title}`);
+              }
